entries[65790] = { ["name"] = "Gegenzauber", ["text"] = "9% von Grundmana 30 Meter Reichweite\nSofort 24 sek. Abklingzeit\nKontert das Zauberwirken des Feindes und verhindert 8 Sek. lang, dass ein Zauber dieser Art der Magie gewirkt werden kann. Führt zu einem hohen Maß an Bedrohung." }
entries[65791] = { ["name"] = "Arkanschlag", ["text"] = "8% von Grundmana 30 Meter Reichweite\nWirken in 2.5 sek.\nÜberzieht einen Feind mit Energie und verursacht 12488 to 14512 Arkanschaden. Mit jedem Wirken von 'Arkanschlag' werden der verursachte Schaden aller Arkanzauber um 10% und die Manakosten von 'Arkanschlag' um 150% erhöht. Dieser Effekt ist bis zu 4-mal stapelbar und hält 6 Sek. lang an oder bis ein Arkanzauber außer 'Arkanschlag' gewirkt wurde." }
entries[65792] = { ["name"] = "Frostnova", ["text"] = "8% von Grundmana\nSofort 25 sek. Abklingzeit\nFügt in der Nähe des Zaubernden befindlichen Feinden 365 to 415 Frostschaden zu und friert sie bis zu 8 Sek. lang ein. Erlittener Schaden kann den Effekt unterbrechen." }
entries[65793] = { ["name"] = "Blinzeln", ["text"] = "21% von Grundmana\nSofort 15 sek. Abklingzeit\nTeleportiert den Zaubernden 20 Meter nach vorn, es sei denn, etwas steht im Weg. Befreit den Zaubernden auch von Betäubungen und Fesseln." }
