entries[65812] = { ["name"] = "Instabiles Gebrechen", ["text"] = "15% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek. 15 sek. Abklingzeit\nSchattenenergie zerstört langsam das Ziel und verursacht im Verlauf von 15 Sek. 23125 to 26875 Schaden. Sollte 'Instabiles Gebrechen' gebannt werden, erleidet der Bannende 13875 to 16125 Schattenschaden und wird 4 Sek. lang zum Schweigen gebracht." }
entries[65813] = { ["name"] = "Instabiles Gebrechen", ["text"] = "Unbegrenzte Reichweite\nSofort\nSollte 'Instabiles Gebrechen' gebannt werden, erleidet der Bannende 13875 to 16125 Schattenschaden und wird 5 Sek. lang zum Schweigen gebracht." }
entries[65814] = { ["name"] = "Fluch der Pein", ["text"] = "10% von Grundmana 30 Meter Reichweite\nSofort\nVerflucht das Ziel mit Pein und fügt 24 Sek. lang insgesamt 42000 Schattenschaden zu. Zuerst wird der Schaden langsam zugefügt und nimmt dann zu, bis der Fluch seine Gesamtdauer erreicht hat. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[65815] = { ["name"] = "Fluch der Erschöpfung", ["text"] = "6% von Grundmana 30 Meter Reichweite\nSofort\nVerringert das Bewegungstempo des Ziels 12 Sek. lang um 50%. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[65816] = { ["name"] = "Höllenfeuer", ["text"] = "64% von Grundmana\nKanalisiert (Wirken in 15 sek.)\nEntzündet den Bereich um den Zaubernden herum, fügt ihm selbst alle 1 Sek. 1500 Feuerschaden zu sowie im gleichen Rhythmus allen in der Nähe befindlichen Feinden 9000 Feuerschaden. Hält 15 Sek. lang an." }
entries[65817] = { ["name"] = "Höllenfeuereffekt", ["text"] = "Sofort\nEntzündet den Bereich um den Zaubernden herum, fügt ihm selbst alle 1 Sek. 1500 Feuerschaden zu sowie im gleichen Rhythmus allen in der Nähe befindlichen Feinden 9000 Feuerschaden. Hält 15 Sek. lang an." }
entries[65819] = { ["name"] = "Sengender Schmerz", ["text"] = "8% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek.\nFügt dem Ziel sengenden Schmerz zu und verursacht 5490 to 6510 Feuerschaden." }
entries[65820] = { ["name"] = "Todesmantel", ["text"] = "23% von Grundmana 30 Meter Reichweite\nSofort 2 min Abklingzeit\nVerursacht 9425 to 10575 Schattenschaden und das betroffene Ziel läuft 3 Sek. lang voller Entsetzen davon. Der Zaubernde erhält 500% des verursachten Schadens in Gesundheit." }
entries[65821] = { ["name"] = "Schattenblitz", ["text"] = "17% von Grundmana 30 Meter Reichweite\nWirken in 2.5 sek.\nSchleudert einen Schattenblitz auf den Feind und verursacht 11813 to 13187 Schattenschaden." }
