entries[65855] = { ["name"] = "Insektenschwarm", ["text"] = "8% von Grundmana 30 Meter Reichweite\nSofort\nDas feindliche Ziel wird von Insekten umschwärmt, die dessen Trefferchance mit Nahkampf- und Distanzangriffen um 3% verringern und beim Betroffenen über 12 Sek. 22200 to 25800 Naturschaden verursachen." }
entries[65856] = { ["name"] = "Mondfeuer", ["text"] = "21% von Grundmana 30 Meter Reichweite\nSofort 5 sek. Abklingzeit\nVerbrennt den Feind und fügt ihm 4140 to 4860 Arkanschaden sowie 12 Sek. lang insgesamt 7000 zusätzlichen Arkanschaden zu." }
entries[65857] = { ["name"] = "Wucherwurzeln", ["text"] = "7% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek. 10 sek. Abklingzeit\nLässt das Ziel an Ort und Stelle festwurzeln und verursacht im Verlauf von 10 Sek. insgesamt 1576.7 to 1756.7 Naturschaden. Erlittener Schaden kann den Effekt unterbrechen." }
entries[65858] = { ["name"] = "Schild des Lichts", ["text"] = "Sofort\nEin heller Schild schützt die Schwester, absorbiert 1200000 Schaden und verhindert 16 Sek. lang das Unterbrechen von Zaubern." }
entries[65859] = { ["name"] = "Wirbelsturm", ["text"] = "8% von Grundmana 20 Meter Reichweite\nWirken in 1.5 sek. 6 sek. Abklingzeit\nWirbelt das Ziel bis zu 6 Sek. lang in die Luft. Während dieser Zeit ist es handlungsunfähig, aber auch unverwundbar. Es kann immer nur ein Ziel gleichzeitig von Eurem Zauber 'Wirbelsturm' betroffen sein." }
entries[65860] = { ["name"] = "Baumrinde", ["text"] = "Sofort 1 min Abklingzeit\nDie Haut des Druiden wird hart wie Rinde. Jeglicher erlittene Schaden wird um 40% verringert. Kann auch gewirkt werden, wenn man betäubt, eingefroren, handlungsunfähig oder in Schlaf versetzt worden ist oder sich fürchtet. In allen Gestalten nutzbar. Hält 12 Sek. lang an." }
entries[65861] = { ["name"] = "Naturgewalt", ["text"] = "12% von Grundmana 30 Meter Reichweite\nSofort 3 min Abklingzeit\nBeschwört 3 Treants, die das Ziel 30 Sek. lang angreifen." }
entries[65862] = { ["name"] = "Zorn", ["text"] = "11% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek.\nFügt dem Ziel 8460 to 9540 Naturschaden zu." }
entries[65863] = { ["name"] = "Feenfeuer", ["text"] = "8% von Grundmana 30 Meter Reichweite\nSofort\nVerringert die Rüstung des Ziels 40 Sek. lang um 15%. Während der Wirkungsdauer kann das Ziel weder Verstohlenheit anwenden noch unsichtbar werden." }
