entries[65877] = { ["name"] = "Wyverngift", ["text"] = "8% von Grundmana 35 Meter Reichweite\n1 min Abklingzeit\nBenötigt Distanzwaffe\nEin Gift, welches das Ziel 8 Sek. lang einschlafen lässt. Jeglicher erlittene Schaden hebt den Effekt wieder auf. Sobald das Ziel erwacht, verursacht der Giftpfeil im Verlauf von 8 Sek. insgesamt 2.6 Naturschaden. Auf dem Ziel kann gleichzeitig nur ein Gift pro Jäger aktiv sein." }
