entries[65932] = { ["name"] = "Gegenschlag", ["text"] = "Sofort 5 min Abklingzeit\nEin sofortiger Gegenangriff gegen jeden Feind, der Euch im Nahkampf schlägt. Hält 12 Sek. lang an. Bei Nahkampfangriffen, die von hinten geführt werden, ist ein Gegenangriff nicht möglich. Maximal 20 Angriffe können 'Gegenschlag' auslösen." }
