entries[66034] = { ["name"] = "Kandierte Süßkartoffel", ["text"] = "Wirken in 2 sek.\nReagenzien:\nSüßkartoffel aus Mulgore , Honig , Herbstliche Gewürze\nBenötigt Pilgerfreudenfest\nBenutzen: Stellt im Verlauf von 30 Sek. pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und Eure Tempowertung und Ausdauer wird 1 Stunde lang um [floor(cond([Quellwert]( 85, 15), 85 - 15, 0) * 0.8) + 4] erhöht.", ["unresolvedValues"] = true }
