entries[66037] = { ["name"] = "Langsam gerösteter Truthahn", ["text"] = "Wirken in 2 sek. 2\nReagenzien:\nWilder Truthahn , Honig (2), Herbstliche Gewürze\nBenötigt Pilgerfreudenfest\nBenutzen: Stellt im Verlauf von 30 Sek. pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und 1 Stunde lang Eure Angriffskraft um [floor(cond([Quellwert]( 85, 15), 85 - 15, 0) * 1.108) + 8] und Eure Ausdauer um [floor(cond([Quellwert]( 85, 15), 85 - 15, 0) * 0.554) + 4] erhöht.", ["unresolvedValues"] = true }
